tool_calls:
#!/bin/bash

while IFS= read -r path || [[ -n "$path" ]]; do
    dir=${path%/*}
    base=${path##*/}
    stem=$base
    ext=

    if [[ "${base#.}" == *.* ]]; then
        ext=${base##*.}
        if [[ -n "$ext" ]]; then
            stem=${base%.*}
        fi
    fi

    printf '%s|%s|%s|%s\n' "$dir" "$base" "$stem" "$ext"
done < /home/eval/data/paths.txt > /home/eval/data/parts.txt

exit 0

